import{_ as o,a as i,b as e,c as m,d as u,e as d}from"./chunks/玥玥和阳阳.9TochpX9.js";import{_ as g,C as t,o as y,c as f,a3 as _,E as p,w as P,j as n}from"./chunks/framework.D3kUw6rp.js";const B=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"article/2025/year-end-summary/02yangyang.md","filePath":"article/2025/year-end-summary/02yangyang.md"}'),T={name:"article/2025/year-end-summary/02yangyang.md"};function b(a,l,C,N,S,V){const r=t("Pictures"),s=t("OneDay");return y(),f("div",null,[l[1]||(l[1]=_('<h2 id="阳阳" tabindex="-1">阳阳 <a class="header-anchor" href="#阳阳" aria-label="Permalink to &quot;阳阳&quot;">​</a></h2><p>今年的最大主角就是我们的阳阳了，说实话他真的是个意外，算是个美丽的意外吧！</p><p>因为玥玥已经让我体验到养育小生命的乐趣且非常满足。</p><p>阳阳的到来像是我们做好了一张非常满意的答卷之余又做了一道附加题，还做对了，bingo! 加分！</p><p>玥玥在世上有了一个手足之情也是挺好的，因为我自己就来自二胎家庭，所以还是很认可姐弟情谊的。</p><p>整个孕期阳阳都表现非常好，不像玥玥把她妈妈折腾得挺够呛。阳阳是平稳到几乎没啥存在感，所有体检都是一路绿灯。</p><p>还特别会挑时间，居然就在国庆这天出生 🇨🇳 ！！</p><p>一路平稳的他却在生产的过程中被感染了，刚生下来就被带到儿科隔离观察，在那边待了七天。</p><p>我们只有在第三天的时候隔着窗户看望了一下:</p><p><img src="'+d+'" alt=""></p><p>可怜的小家伙，我们只是匆匆看了一眼就被医生抱走了，不过由于是较为常见的 <code>B 组链球菌病</code> 所以也没有特别焦虑，而且小宝宝在七天之后也顺利的出院了。</p><p>就在满月之际，由于玥玥得了流感，导致阳阳也感染了，由咳嗽引发了肺炎，幸亏我们较为及时的带去医院门诊，当天就被告知需要住院观察。</p><p>于是我们又在医院待了一周左右，第一天需要打一个点滴护士找不到血管也受了罪。因为是婴幼儿，所以住院也是物理治疗和观察为主，唯独用吸管吸插入鼻孔和喉咙吸鼻涕的时候真的是遭老罪了，小小的身体痛苦得直哆嗦，。</p><p>才出生一个月就受这个罪太心疼了：</p>',14)),p(r,{width:300},{default:P(()=>[...l[0]||(l[0]=[n("img",{loading:"lazy",src:o},null,-1),n("img",{loading:"lazy",src:i},null,-1),n("img",{loading:"lazy",src:e},null,-1)])]),_:1}),l[2]||(l[2]=n("blockquote",null,[n("p",null,"当下社会的医患关系处于信任危机时期，我不得不说厦门中医院的医生和护士都是比较负责且有爱心的。我们两次都是在这边生产，能感受到来自医生护士们的人情关怀。")],-1)),l[3]||(l[3]=n("p",null,"期间刚好公司开始 996 ，我从「家 - 公司」 变成了 「医院 - 公司」 的两点一线。 白天公司上班，下班之后就去医院过夜，和玥妈一起照顾阳阳。",-1)),l[4]||(l[4]=n("p",null,"好在我们住院一周之后，咳嗽和鼻涕都控制下来了，我们就办理了出院。 回到家中，精心照看，如今马上就要满 3个月了。",-1)),l[5]||(l[5]=n("p",null,"再也没有生病了，一直健健康康的成长，感觉长得好快，可能是男孩子，体感上比玥玥当时健壮很多。",-1)),l[6]||(l[6]=n("p",null,"他外婆来伺候了一个月的月子，都是跟他外婆睡，外婆回去之后，我就接任了晚上带娃的任务。",-1)),l[7]||(l[7]=n("p",null,"所以这两个月我的状态就是 白天996，晚上带阳阳睡小房子，夜里起来 3 趟左右，泡奶，哄睡。（他奶奶每次也会起来帮忙换尿布，泡奶什么的）",-1)),p(s,{data:a.data},null,8,["data"]),l[8]||(l[8]=n("p",null,"说实话感觉还好，由于小家伙基本都是吃完就睡，所以夜里没有特别折腾，醒了之后他奶奶抓紧换尿布，然后我快速去泡奶，只要在他情绪爆发之前及时的把奶嘴塞到他嘴里，就风平浪静。",-1)),l[9]||(l[9]=n("p",null,"后面的日子就这样安稳的过来了，小家伙静悄悄的长大，再也没折腾过我们。",-1)),l[10]||(l[10]=n("p",null,[n("img",{src:m,alt:""})],-1)),l[11]||(l[11]=n("p",null,"写文字的此刻（2026年1月1日 00:27） 他刚好满 3 个月啦！！！",-1)),l[12]||(l[12]=n("p",null,"有必要在阳阳的片段里再夸一下玥玥，弟弟刚出生的时候不愿意让我们抱弟弟，只允许外婆和奶奶去抱弟弟。",-1)),l[13]||(l[13]=n("p",null,"她外婆走后，自然而然的，她就不再强行霸占了，会接受爸爸妈妈需要抱弟弟的事实。只有偶尔闹脾气的时候会不让我抱弟弟，一般这种情况我都会依着她，毕竟她已经非常棒了。我们不会要求她一瞬间长大。",-1)),l[14]||(l[14]=n("p",null,[n("img",{src:u,alt:""})],-1))])}const D=g(T,[["render",b]]);export{B as __pageData,D as default};
